(function () {
  'use strict';
  const S = window.Studio;
  const E = S.escape;
  const number = n => Number(n || 0).toLocaleString('zh-CN');
  const money = n => '¥' + Number(n || 0).toFixed(2);
  const compact = n => n >= 1000000 ? (n / 1000000).toFixed(2) + 'M' : n >= 1000 ? (n / 1000).toFixed(1) + 'k' : String(n);
  const gov = S.state.gov || (S.state.gov = { budget: 300, threshold: 80, preferences: { name: '我的创作空间', defaultModel: 'GPT-4.1', approval: true, digest: true }, evaluations: [] });
  gov.preferences = gov.preferences || { name: '我的创作空间', defaultModel: 'GPT-4.1', approval: true, digest: true };
  gov.evaluations = gov.evaluations || [];
  S.state.budget = Number(gov.budget) || 300;
  const monthDays=()=>Number(new Intl.DateTimeFormat('en',{timeZone:'Asia/Shanghai',day:'numeric'}).format(new Date()));
  S.usageSummary = () => { const data = usageData(monthDays()); const budget = Number(gov.budget) || 300; return { cost: data.cost, tokens: data.tokens, budget, ratio: data.cost / budget }; };
  if (!S.state.models) S.state.models = [
    { id: 'model-gpt', name: 'GPT-4.1', provider: 'OpenAI', type: '对话模型', endpoint: 'https://api.openai.com/v1', status: 'connected' },
    { id: 'model-claude', name: 'Claude Sonnet', provider: 'Anthropic', type: '对话模型', endpoint: 'https://api.anthropic.com', status: 'connected' },
    { id: 'model-embed', name: 'text-embedding', provider: '自定义', type: '嵌入模型', endpoint: 'https://your-model.example/v1', status: 'disabled' }
  ];
  const draftDeploy = { project: 'otryx-studio', port: '8080', generated: false, file: 'compose' };
  const agents = () => S.state.agents || [];
  const modelName = run => { const agent = agents().find(a => a.id === run.agent || a.name === run.agent); return run.model || (agent && agent.model) || 'GPT-4.1'; };
  const agentName = run => { const agent = agents().find(a => a.id === run.agent || a.name === run.agent); return (agent && agent.name) || run.agent || '工作台任务'; };
  const selectedDays = () => S.params.days === '7' ? 7 : 30;
  const selectedGroup = () => ['model', 'agent', 'task'].includes(S.params.group) ? S.params.group : 'model';
  const dayText = date => date.toLocaleDateString('zh-CN', { month: '2-digit', day: '2-digit', timeZone: 'Asia/Shanghai' });
  function usageData(days) {
    const base = new Date();
    const dayData = Array.from({length:days},(_,i)=>{const date=new Date(base);date.setUTCDate(base.getUTCDate()-days+i+1);return {date,label:dayText(date),tokens:0,cost:0,runs:0};});
    const rows=[];
    (S.state.runs||[]).filter(run=>run.engine).forEach(run=>{
      const date=new Date(run.created);if(Number.isNaN(date.getTime())||date>base)return;
      const found=dayData.find(d=>d.label===dayText(date));if(!found)return;
      const tokens=Number(run.tokens)||0,cost=Number(run.cost)||0;
      found.tokens+=tokens;found.cost+=cost;found.runs++;
      rows.push({id:run.id,date:found.label,timestamp:date.getTime(),title:run.title,agent:agentName(run),model:modelName(run),tokens,cost,status:'本地运行'});
    });
    return {days:dayData,rows,tokens:rows.reduce((n,r)=>n+r.tokens,0),cost:rows.reduce((n,r)=>n+r.cost,0),count:rows.length};
  }
  function groupUsage(rows, group) {
    if (group === 'task') return [...rows].sort((a,b)=>b.timestamp-a.timestamp);
    const map = new Map();
    rows.forEach(r => { const key = group === 'agent' ? r.agent : r.model; const row = map.get(key) || { name: key, tokens: 0, cost: 0, count: 0 }; row.tokens += r.tokens; row.cost += r.cost; row.count++; map.set(key, row); });
    return Array.from(map.values()).sort((a, b) => b.tokens - a.tokens);
  }
  function usageChart(data) {
    const width = 840, height = 220, left = 44, right = 18, top = 20, bottom = 34;
    const max = Math.max(1000,Math.ceil(Math.max(...data.map(d => d.tokens)) / 20000) * 20000);
    const x = i => left + i * (width - left - right) / (data.length - 1);
    const y = n => height - bottom - n / max * (height - top - bottom);
    const line = data.map((d, i) => `${i ? 'L' : 'M'} ${x(i).toFixed(1)} ${y(d.tokens).toFixed(1)}`).join(' ');
    const area = `${line} L ${x(data.length - 1)} ${height - bottom} L ${left} ${height - bottom} Z`;
    return `<div class="gov-chart"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${data.length} 天演示 Token 用量趋势；每个数据点可以通过键盘查看详情"><defs><linearGradient id="gov-area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="currentColor" stop-opacity=".17"/><stop offset="100%" stop-color="currentColor" stop-opacity=".015"/></linearGradient></defs>${[0, .5, 1].map(t => `<line class="gov-chart-grid" x1="${left}" x2="${width - right}" y1="${y(max * t)}" y2="${y(max * t)}"/><text class="gov-axis-label" x="${left - 10}" y="${y(max * t) + 4}" text-anchor="end">${compact(max * t)}</text>`).join('')}<path d="${area}" fill="url(#gov-area)"/><path d="${line}" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linejoin="round" stroke-linecap="round"/>${data.map((d, i) => `<circle class="gov-chart-point" cx="${x(i)}" cy="${y(d.tokens)}" r="4" tabindex="0" data-gov-point="${i}" aria-label="${d.label}，${number(d.tokens)} Token，演示费用 ${money(d.cost)}"><title>${d.label} · ${number(d.tokens)} Token · ${money(d.cost)}</title></circle>`).join('')}${[0, Math.round((data.length - 1) / 3), Math.round(2 * (data.length - 1) / 3), data.length - 1].map(i => `<text class="gov-axis-label" x="${x(i)}" y="${height - 8}" text-anchor="middle">${data[i].label}</text>`).join('')}</svg><div class="gov-chart-caption" id="gov-chart-tip" role="status">${S.icon('chart', 14)} <span>聚焦或移入数据点，查看当天明细</span></div></div>`;
  }
  S.page('usage', { title: '用量与成本', section: '治理', render() {
    const days = selectedDays(), group = selectedGroup(), data = usageData(days), monthly = usageData(monthDays());
    const rows = groupUsage(data.rows, group); const page = Math.max(1, Math.min(Number(S.params.page) || 1, Math.ceil(rows.length / 8) || 1)); const visible = rows.slice((page - 1) * 8, page * 8);
    const budget = Number(gov.budget) || 300; const ratio = monthly.cost / budget * 100;
    return `<div class="gov-page">${S.header('', '用量与成本', '按模型、Agent 和任务查看本地运行的用量；费用为模拟估算。', S.btn('导出 CSV', 'gov-export-usage', { icon: 'download' }))}<div class="gov-usage-layout"><section class="panel gov-trend-panel"><div class="gov-panel-head"><div><h2 class="section-title">用量趋势</h2><p class="muted small">演示用量 · Token</p></div><div class="gov-segment" aria-label="日期范围">${[7, 30].map(n => `<button type="button" class="${days === n ? 'is-active' : ''}" data-action="gov-days" data-days="${n}" aria-pressed="${days === n}">近 ${n} 天</button>`).join('')}</div></div><div class="gov-inline-metrics"><div><span class="metric-label">累计 Token</span><strong>${compact(data.tokens)}</strong><span class="small muted">${number(data.tokens)} Token</span></div><div><span class="metric-label">模拟费用</span><strong>${money(data.cost)}</strong><span class="small muted">非真实账单或模型报价</span></div><div><span class="metric-label">调用任务</span><strong>${number(data.count)}</strong><span class="small muted">当前日期范围内的运行</span></div></div>${usageChart(data.days)}</section><aside class="panel gov-budget"><div class="row between"><span class="gov-icon-tile">${S.icon('wallet', 20)}</span>${S.badge(ratio >= 100 ? '已超出预算' : ratio >= gov.threshold ? '接近提醒线' : '预算充裕', ratio >= gov.threshold ? 'warning' : 'success')}</div><h2>本月预算</h2><p class="muted small">本月模拟预算</p><div class="gov-budget-total">${money(monthly.cost)} <span>/ ${money(budget)}</span></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(ratio, 100).toFixed(1)}%"></div></div><p class="small muted">已使用 ${ratio.toFixed(1)}% · 达到 ${gov.threshold}% 时显示提醒</p><div class="gov-budget-bottom">${S.btn('调整预算', 'gov-budget', { icon: 'settings', variant: 'secondary' })}<span class="small muted">仅用于演示提示，不限制真实服务</span></div></aside></div><section class="panel gov-ledger"><div class="gov-panel-head"><div><h2 class="section-title">调用明细</h2><p class="small muted">${group === 'task' ? '按发生时间排列本地运行' : '汇总当前日期范围内的本地运行'}</p></div>${S.tabs([{ id: 'model', label: '按模型' }, { id: 'agent', label: '按 Agent' }, { id: 'task', label: '按任务' }], group, 'gov-group')}</div><div class="table-wrap"><table class="data-table"><thead><tr>${group === 'task' ? '<th>任务 / 来源</th><th>模型</th><th>日期</th>' : `<th>${group === 'model' ? '模型' : 'Agent'}</th><th>记录数</th><th>用量占比</th>`}<th class="gov-num">Token</th><th class="gov-num">模拟费用</th></tr></thead><tbody>${visible.map(row => group === 'task' ? `<tr><td><strong>${E(row.title)}</strong><div class="small muted">${E(row.agent)} · ${E(row.status)}</div></td><td>${E(row.model)}</td><td class="mono">${row.date}</td><td class="gov-num mono">${number(row.tokens)}</td><td class="gov-num mono">${money(row.cost)}</td></tr>` : `<tr><td><span class="gov-table-identity"><span class="gov-model-dot">${S.icon(group === 'model' ? 'box' : 'agent', 16)}</span><strong>${E(row.name)}</strong></span></td><td class="mono">${row.count}</td><td><div class="gov-share"><span style="width:${Math.max(2, row.tokens / (data.tokens||1) * 100)}%"></span></div><span class="small muted">${(row.tokens / (data.tokens||1) * 100).toFixed(1)}%</span></td><td class="gov-num mono">${number(row.tokens)}</td><td class="gov-num mono">${money(row.cost)}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">当前日期范围内没有运行记录。完成一次对话、调试或 API 调用后会显示在这里。</td></tr>'}</tbody></table></div><div class="gov-table-footer"><span class="small muted">共 ${rows.length} ${group === 'task' ? '条记录' : '项'} · 第 ${page} / ${Math.ceil(rows.length / 8) || 1} 页</span><div class="row">${S.btn('上一页', 'gov-usage-page', { variant: 'secondary', small: true, attrs: `data-page="${page - 1}" ${page <= 1 ? 'disabled' : ''}` })}${S.btn('下一页', 'gov-usage-page', { variant: 'secondary', small: true, attrs: `data-page="${page + 1}" ${page * 8 >= rows.length ? 'disabled' : ''}` })}</div></div></section><p class="gov-footnote">${S.icon('help', 14)} 原型中的费用使用固定示例估算，仅用于展示产品交互，不代表任何服务商的实际价格。</p></div>`;
  }, mount(container) {
    const data = usageData(selectedDays()); const tip = container.querySelector('#gov-chart-tip');
    const show = event => { const point = event.target.closest('[data-gov-point]'); if (!point) return; const d = data.days[Number(point.dataset.govPoint)]; tip.innerHTML = `${S.icon('chart', 14)} <span><strong>${d.label}</strong> · ${number(d.tokens)} Token · 模拟费用 ${money(d.cost)}</span>`; };
    container.addEventListener('mouseover', show); container.addEventListener('focusin', show);
    return () => { container.removeEventListener('mouseover', show); container.removeEventListener('focusin', show); };
  } });
  S.action('gov-days', el => S.go('usage', { ...S.params, days: el.dataset.days, page: 1 }));
  S.action('gov-group', el => S.go('usage', { ...S.params, group: el.dataset.id || el.dataset.tab || el.dataset.value, page: 1 }));
  S.action('gov-usage-page', el => S.go('usage', { ...S.params, page: el.dataset.page }));
  S.action('gov-export-usage', () => {
    const rows = usageData(selectedDays()).rows;
    const csv = [['日期', '任务', 'Agent', '模型', 'Token', '模拟费用（元）', '记录来源'], ...rows.map(r => [r.date, r.title, r.agent, r.model, r.tokens, r.cost.toFixed(4), r.status])].map(row => row.map(value => '"' + String(value).replace(/"/g, '""') + '"').join(',')).join('\r\n');
    S.download('otryx-demo-usage-' + selectedDays() + 'days.csv', '\ufeff' + csv, 'text/csv;charset=utf-8'); S.toast('演示用量 CSV 已生成，共 ' + rows.length + ' 条记录');
  });
  S.action('gov-budget', () => S.modal({ title: '调整演示预算', subtitle: '设置本地账本的提醒线，不会产生支付、扣款或限制外部模型服务。', body: `<form id="gov-budget-form" data-form="gov-budget-form" novalidate>${S.field('月度模拟预算（元）', { id: 'gov-budget-value', name: 'budget', value: gov.budget, type: 'number', required: true, help: '请输入 1–100,000 之间的金额。' })}${S.field('提醒阈值（%）', { id: 'gov-budget-threshold', name: 'threshold', value: gov.threshold, type: 'number', required: true, help: '模拟用量达到该比例时，在账本显示提醒。' })}</form>`, footer: S.btn('保存预算', 'gov-budget-save', { variant: 'primary' }) }));
  S.action('gov-budget-save', () => { const form = document.getElementById('gov-budget-form'); if (!S.validate(form, { budget: v => +v >= 1 && +v <= 100000 ? null : '请输入 1–100,000 之间的金额', threshold: v => +v >= 1 && +v <= 100 ? null : '请输入 1–100 之间的比例' })) return; gov.budget = +form.elements.budget.value; S.state.budget = gov.budget; gov.threshold = +form.elements.threshold.value; S.save(); S.closeModal(); S.render(); S.toast('演示预算已更新'); });

  const settingsTab = () => ['models', 'preferences', 'deploy'].includes(S.params.tab) ? S.params.tab : 'models';
  S.page('settings', { title: '空间设置', section: '治理', render() {
    const tab = settingsTab();
    return `<div class="gov-page">${S.header('空间设置', '管理你的工作空间', '配置个人偏好与部署草案，模型统一在模型中心维护。')}<div class="gov-settings-tabs">${S.tabs([{ id: 'models', label: '模型中心入口' }, { id: 'preferences', label: '空间偏好' }, { id: 'deploy', label: '部署引导' }], tab, 'gov-settings-tab')}</div>${tab === 'models' ? renderModels() : tab === 'preferences' ? renderPreferences() : renderDeployment()}</div>`;
  } });
  S.action('gov-settings-tab', el => S.go('settings', { tab: el.dataset.id || el.dataset.tab || el.dataset.value }));
  function renderModels() {
    const models=S.Models?.list()||S.state.models||[];
    return `<section class="panel gov-preferences"><div class="gov-panel-head"><div><h2 class="section-title">模型在模型中心统一维护</h2><p class="small muted">${models.length} 个模型实例。服务商连接、模型类型、能力声明、调试与默认用途都在同一处管理。</p></div><span class="gov-icon-tile">${S.icon('box',20)}</span></div><p class="muted">语言、向量、重排、图像与语音模型分别配置，已有 Agent 和工作流引用保留。</p><a class="btn btn-primary" href="#models">打开模型中心</a></section>`;
  }
  S.action('gov-model-add',()=>S.Models?S.Models.openModel():S.go('models'));
  S.action('gov-model-edit',el=>S.Models?S.Models.openModel(el.dataset.id):S.go('models'));
  S.action('gov-model-toggle',el=>S.go('model-detail',{id:el.dataset.id}));
  function renderPreferences() {
    const p = gov.preferences;
    return `<section class="panel gov-preferences"><div class="gov-panel-head"><div><h2 class="section-title">个人空间</h2><p class="small muted">这里的偏好保存在当前浏览器</p></div><span class="gov-icon-tile">${S.icon('users', 20)}</span></div><form id="gov-preferences-form" data-form="gov-preferences-form" novalidate>${S.field('空间名称', { id: 'gov-space-name', name: 'spaceName', value: window.StudioSpaces?.active()?.name || S.state.spaceName || p.name, required: true })}<div class="field"><label class="field-label" for="gov-default-model">偏好模型</label><select class="select" id="gov-default-model" name="defaultModel">${S.Models?.selectionOptions?S.Models.selectionOptions('llm',p.defaultModel):(S.Models?S.Models.list({type:'llm',enabled:true}):S.state.models).map(m => `<option value="${E(m.id)}" ${m.id === p.defaultModel || m.name === p.defaultModel ? 'selected' : ''}>${E(m.name)}</option>`).join('')}</select><p class="field-help">用于工作台的新任务；已有 Agent 仍使用各自的模型配置。</p></div><div class="gov-preference-row"><div><strong>在工作台突出待确认任务</strong><p class="small muted">工作台优先展示待确认任务；审批流程按各自任务配置执行。</p></div><input type="checkbox" name="approval" ${p.approval ? 'checked' : ''} aria-label="突出待确认任务"/></div><div class="gov-preference-row"><div><strong>显示用量摘要</strong><p class="small muted">在工作台和侧栏显示当前用量摘要。</p></div><input type="checkbox" name="digest" ${p.digest ? 'checked' : ''} aria-label="保存用量摘要偏好"/></div><div class="gov-preference-footer"><span class="small muted">语言：${window.StudioAppearance?.getLocale()==='en-US'?'English':'简体中文'} · 时区：Asia/Shanghai</span><div class="row">${S.btn('重置演示', 'reset-demo', { variant: 'ghost' })}${S.btn('保存偏好', 'gov-preferences-save', { variant: 'primary' })}</div></div></form></section>`;
  }
  S.action('gov-preferences-save', () => { const form = document.getElementById('gov-preferences-form'); if (!S.validate(form, { spaceName: v => v.trim()&&v.trim().length<=42 ? null : '空间名称须为 1–42 个字符' })) return; if(S.Models)S.Models.resolve(form.elements.defaultModel.value,{type:'llm'}); const active=window.StudioSpaces?.active(); if(active&&active.name!==form.elements.spaceName.value.trim())window.StudioSpaces.rename(active.id,form.elements.spaceName.value); gov.preferences = { name: active?window.StudioSpaces.active().name:form.elements.spaceName.value.trim(), defaultModel: form.elements.defaultModel.value, approval: form.elements.approval.checked, digest: form.elements.digest.checked }; S.state.spaceName = gov.preferences.name; if(S.save()===false){S.toast('空间偏好尚未持久保存，请检查浏览器存储。','warning');return;} S.session.model = gov.preferences.defaultModel; if(S.renderChrome)S.renderChrome(); S.toast('个人空间偏好已保存'); });
  function composeDraft() {
    return `# OTRYX Studio — 部署配置草案\n# 此原型没有对应的可拉取 OTRYX 镜像。请先实现后端、构建并填写你自己的镜像。\n# 未完成 .env 配置与安全审查前，不可直接用于生产。\nname: ${draftDeploy.project}\nservices:\n  studio:\n    image: \${OTRYX_STUDIO_IMAGE:?请填写自行构建的前端镜像}\n    ports:\n      - "127.0.0.1:${draftDeploy.port}:80"\n    depends_on:\n      - api\n  api:\n    image: \${OTRYX_API_IMAGE:?请填写自行实现的 API 镜像}\n    environment:\n      DATABASE_URL: \${DATABASE_URL:?请填写数据库连接}\n      REDIS_URL: redis://redis:6379\n      ENCRYPTION_KEY: \${ENCRYPTION_KEY:?请设置服务端加密密钥}\n    depends_on:\n      - postgres\n      - redis\n  runtime:\n    image: \${OTRYX_RUNTIME_IMAGE:?请填写自行实现的任务运行时镜像}\n    environment:\n      DATABASE_URL: \${DATABASE_URL:?请填写数据库连接}\n      REDIS_URL: redis://redis:6379\n    depends_on:\n      - api\n  postgres:\n    image: \${POSTGRES_IMAGE:?请填写已审查的 PostgreSQL 镜像}\n    environment:\n      POSTGRES_DB: otryx\n      POSTGRES_USER: otryx\n      POSTGRES_PASSWORD: \${POSTGRES_PASSWORD:?请设置数据库密码}\n    volumes:\n      - postgres_data:/var/lib/postgresql/data\n  redis:\n    image: \${REDIS_IMAGE:?请填写已审查的 Redis 镜像}\n    volumes:\n      - redis_data:/data\nvolumes:\n  postgres_data:\n  redis_data:\n`;
  }
  function envDraft() { return `# 示例文件：所有 REPLACE_ 值都需要替换；不得提交真实凭证到仓库。\n# example.invalid 为明确的占位域，不存在可拉取的官方 OTRYX 镜像。\nOTRYX_STUDIO_IMAGE=example.invalid/otryx/studio:REPLACE_WITH_YOUR_BUILD\nOTRYX_API_IMAGE=example.invalid/otryx/api:REPLACE_WITH_YOUR_BUILD\nOTRYX_RUNTIME_IMAGE=example.invalid/otryx/runtime:REPLACE_WITH_YOUR_BUILD\nPOSTGRES_IMAGE=REPLACE_WITH_REVIEWED_POSTGRES_IMAGE\nREDIS_IMAGE=REPLACE_WITH_REVIEWED_REDIS_IMAGE\nPOSTGRES_PASSWORD=REPLACE_WITH_SECURE_PASSWORD\nDATABASE_URL=postgresql://otryx:REPLACE_WITH_SECURE_PASSWORD@postgres:5432/otryx\nENCRYPTION_KEY=REPLACE_WITH_SERVER_ENCRYPTION_KEY\n`; }
  function deployReadme() { return `# OTRYX Studio 部署准备清单\n\n此文件与 docker-compose.yaml、.env.example 均为架构配置草案。\nHTML 原型仅演示前端交互，未包含 API、任务运行时或真实模型集成。\n下载不代表已经部署，也不存在由本原型提供的可拉取 OTRYX 镜像。\n\n1. 实现并测试 API、身份认证、权限、数据库迁移、任务运行时与模型网关。\n2. 为前端/API/runtime 构建自己的容器镜像，并审查基础镜像版本。\n3. 复制 .env.example 为 .env；替换全部占位符，配置独立强密码。\n4. 将真实模型凭证接入服务端秘密管理方案，不存于浏览器或版本库。\n5. 配置健康检查、备份、TLS、反向代理、日志脱敏与资源限制。\n6. 核验 Docker Compose 配置后，在隔离环境手动试运行并检查全部服务。\n7. 验证任务审批、恢复、版本固定、租户隔离与失败重试后再考虑生产。\n\n当前草案项目名：${draftDeploy.project}\n前端仅绑定本机：127.0.0.1:${draftDeploy.port}\n\n此原型没有执行任何部署命令，也没有建立真实服务连接。\n`; }
  function renderDeployment() {
    const fileText = draftDeploy.file === 'env' ? envDraft() : draftDeploy.file === 'readme' ? deployReadme() : composeDraft();
    const filename = draftDeploy.file === 'env' ? '.env.example' : draftDeploy.file === 'readme' ? 'DEPLOYMENT-CHECKLIST.md' : 'docker-compose.yaml';
    return `<div class="gov-deploy-intro"><div><span class="eyebrow">SELF-HOST / 部署准备</span><h2>从个人工作室，到自己的环境。</h2><p class="muted">以 Docker Compose 结构梳理前端、API、任务运行时与数据服务。当前仅生成配置草案。</p></div>${S.badge('尚未部署 · 仅示例', 'warning')}</div><div class="gov-deploy-layout"><section class="panel gov-deploy-plan"><h3 class="section-title">一份可核对的部署方案</h3><div class="gov-deploy-steps">${[['01', '准备自己的镜像', '原型不包含后端与运行时，须自行实现、构建和审查。'], ['02', '填写环境与凭证', '替换所有占位符，配置服务端凭证管理、数据库与缓存。'], ['03', '在隔离环境验证', '补齐健康检查、迁移、备份、TLS，再手动部署验证。']].map(([n, t, d]) => `<div><span>${n}</span><section><h4>${t}</h4><p>${d}</p></section></div>`).join('')}</div><form id="gov-deploy-form" data-form="gov-deploy-form" novalidate>${S.field('项目名称', { id: 'gov-deploy-project', name: 'project', value: draftDeploy.project, required: true })}${S.field('本机访问端口', { id: 'gov-deploy-port', name: 'port', value: draftDeploy.port, type: 'number', required: true })}${S.btn('生成配置草案', 'gov-deploy-generate', { icon: 'code', variant: 'primary' })}</form><p class="small muted gov-deploy-local">仅绑定 127.0.0.1，配置无真实凭证。生成与下载不会执行部署。</p></section><section class="panel gov-code-panel"><div class="gov-panel-head"><div><h3 class="section-title">${filename}</h3><p class="small muted">${draftDeploy.generated ? '已根据表单生成' : '配置结构预览'} · 占位镜像无法直接运行</p></div>${S.btn('复制', 'gov-deploy-copy', { variant: 'secondary', small: true, icon: 'copy' })}</div><div class="gov-code-tabs">${S.tabs([{ id: 'compose', label: 'Compose' }, { id: 'env', label: '环境变量' }, { id: 'readme', label: '准备清单' }], draftDeploy.file, 'gov-deploy-file')}</div><pre class="gov-code"><code>${E(fileText)}</code></pre><div class="gov-code-downloads">${S.btn('下载 YAML', 'gov-deploy-download', { variant: 'secondary', small: true, icon: 'download', attrs: 'data-file="compose"' })}${S.btn('下载 .env.example', 'gov-deploy-download', { variant: 'secondary', small: true, icon: 'download', attrs: 'data-file="env"' })}${S.btn('下载清单', 'gov-deploy-download', { variant: 'secondary', small: true, icon: 'download', attrs: 'data-file="readme"' })}</div></section></div>`;
  }
  S.action('gov-deploy-generate', () => { const form = document.getElementById('gov-deploy-form'); if (!S.validate(form, { project: v => /^[a-z0-9][a-z0-9-]{1,30}$/.test(v) ? null : '使用 2–31 位小写字母、数字与连字符', port: v => Number.isInteger(+v) && +v >= 1024 && +v <= 65535 ? null : '请输入 1024–65535 之间的整数端口' })) return; draftDeploy.project = form.elements.project.value; draftDeploy.port = form.elements.port.value; draftDeploy.generated = true; S.render(); S.toast('配置草案已生成，未执行任何部署'); });
  S.action('gov-deploy-file', el => { draftDeploy.file = el.dataset.id || el.dataset.tab || el.dataset.value; S.render(); });
  S.action('gov-deploy-copy', () => S.copy(draftDeploy.file === 'env' ? envDraft() : draftDeploy.file === 'readme' ? deployReadme() : composeDraft()));
  S.action('gov-deploy-download', el => { const type = el.dataset.file; S.download(type === 'env' ? '.env.example' : type === 'readme' ? 'DEPLOYMENT-CHECKLIST.md' : 'docker-compose.yaml', type === 'env' ? envDraft() : type === 'readme' ? deployReadme() : composeDraft(), type === 'compose' ? 'application/yaml' : 'text/plain;charset=utf-8'); S.toast('部署配置草案已下载；请先阅读准备清单'); });
  if (S.form) [['budget', 'gov-budget-save'], ['preferences', 'gov-preferences-save'], ['deploy', 'gov-deploy-generate']].forEach(([name, action]) => S.form('gov-' + name + '-form', () => S.actions[action]()));
}());
